import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>The original implementation reused a parser instance and configured
 * {@code ParserOptions} inside a synchronized block.  Because the parser (and its
 * default options) can be shared across threads, the configuration could be
 * overridden by another thread before the XML was parsed, re‑enabling entity
 * resolution and re‑introducing an XXE vulnerability.</p>
 *
 * <p>This patched version creates a fresh {@link Parser} for each call,
 * configures a dedicated {@link ParserOptions} instance with entity resolution
 * explicitly disabled, and applies those options to the parser before parsing.
 * No synchronization is required, eliminating the race condition.</p>
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    /** Shared {@link Abdera} engine – thread‑safe for creating parsers. */
    private static final Abdera ATOM_ENGINE = new Abdera();

    /** Whether the parser should try to autodetect the character set. */
    private boolean autodetectCharset;

    // -----------------------------------------------------------------------
    // MessageBodyReader implementation
    // -----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Defensive null‑check – the JAX‑RS contract guarantees a non‑null
        // InputStream, but we guard against programming errors.
        if (entityStream == null) {
            throw new IllegalArgumentException("InputStream must not be null");
        }

        // Create a brand‑new parser for this request.  The parser itself is
        // lightweight and does not retain state between invocations.
        Parser parser = ATOM_ENGINE.getParser();

        // Configure parser options securely.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disallow any external entity resolution – this is the core XXE mitigation.
        options.setResolveEntities(false);
        // Explicitly disable DTD processing if the underlying parser supports it.
        // This call is safe even if the implementation does not expose the method.
        try {
            options.setExpandEntityReferences(false);
        } catch (NoSuchMethodError | UnsupportedOperationException ignored) {
            // Older versions of Abdera may not have this method; the
            // setResolveEntities(false) call already provides the essential protection.
        }
        parser.setParserOptions(options);

        // Parse the stream.  Any parsing exception is wrapped as an IOException
        // to satisfy the MessageBodyReader contract.
        Document<T> doc;
        try {
            doc = parser.parse(entityStream);
        } catch (RuntimeException e) {
            // Convert unchecked parsing errors to a checked IOException.
            throw new IOException("Failed to parse Atom XML payload", e);
        }

        // The document root is the element we need to return.
        return doc.getRoot();
    }

