import org.apache.commons.lang3.StringUtils;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * URLValidator – validates URL fields.
 *
 * The original implementation returned a very large regular expression when
 * both {@code urlRegexExpression} and {@code urlRegex} were {@code null} or empty.
 * That expression caused excessive back‑tracking and could be abused to trigger
 * a denial‑of‑service (DoS) condition.  The patched version adds defensive
 * checks, safe fallback handling and logs unexpected situations.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    private String urlRegex;
    private String urlRegexExpression;

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Returns a regular expression that can be used for client‑side URL validation.
     *
     * <p>Behaviour:
     * <ul>
     *   <li>If {@code urlRegexExpression} is supplied, it is parsed and the result
     *       is returned (provided the parsed value is non‑blank).</li>
     *   <li>Otherwise, if {@code urlRegex} is supplied, it is returned directly.</li>
     *   <li>If neither is supplied, a concise, safe default regex is returned.
     *       The default avoids the pathological back‑tracking of the previous
     *       implementation.</li>
     * </ul>
     *
     * @return a non‑null regular‑expression string suitable for URL validation.
     */
    public String getUrlRegex() {
        // 1. Prefer the expression supplied by the user (if any)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                String parsed = (String) parse(urlRegexExpression, String.class);
                if (StringUtils.isNotBlank(parsed)) {
                    return parsed;
                } else {
                    LOG.log(Level.WARNING,
                            "Parsed urlRegexExpression resulted in a blank string; falling back to other options.");
                }
            } catch (Exception e) {
                // Parsing failed – log the problem and continue with fallback logic.
                LOG.log(Level.WARNING,
                        "Failed to parse urlRegexExpression; falling back to other options.", e);
            }
        }

        // 2. Use the simple regex supplied directly (if any)
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // 3. Safe default – a compact pattern that validates http, https and ftp URLs
        //    without the heavy back‑tracking of the original massive expression.
        //    This pattern checks:
        //      • scheme (http, https, ftp)
        //      • "://"
        //      • at least one non‑space character that is not a slash (domain start)
        //      • any characters except whitespace thereafter.
        return "^(https?|ftp)://[^\\s/$.?#].[^\\s]*$";
    }

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------
}
