static public File allocateFile(File dir, String name) throws IllegalArgumentException {
    if (dir == null) throw new IllegalArgumentException("Directory must not be null");
    if (name == null) throw new IllegalArgumentException("File name must not be null");
    // strip query part
    int q = name.indexOf('?');
    if (q > 0) {
        name = name.substring(0, q);
    }
    // reject path separators
    if (name.contains("/") || name.contains("\\") || name.contains("..")) {
        throw new IllegalArgumentException("Invalid file name");
    }
    // ensure name not empty after sanitization
    if (name.isEmpty()) {
        throw new IllegalArgumentException("File name is empty");
    }

    // Resolve against dir and normalize
    Path dirPath = dir.toPath().toAbsolutePath().normalize();
    Path targetPath = dirPath.resolve(name).normalize();

    // Verify targetPath is within dirPath
    if (!targetPath.startsWith(dirPath)) {
        throw new IllegalArgumentException("Resulting file path is outside the target directory");
    }

    File file = targetPath.toFile();

    // generate unique name if exists
    int dot = name.lastIndexOf('.');
    String prefix = dot < 0 ? name : name.substring(0, dot);
    String suffix = dot < 0 ? "" : name.substring(dot);
    int index = 2;
    while (file.exists()) {
        String newName = prefix + "-" + index++ + suffix;
        // re-validate newName (should not contain separators)
        // but we control it, safe.
        targetPath = dirPath.resolve(newName).normalize();
        file = targetPath.toFile();
    }

    // Ensure parent directories exist
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        // If mkdirs failed and not a directory, throw
        throw new IllegalStateException("Failed to create directories for " + parent);
    }

    return file;
}

