import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

/**
 * Utility methods for importing files.
 *
 * <p>This class provides a safe {@code allocateFile} implementation that prevents
 * directory‑traversal attacks. The method validates the supplied {@code name},
 * resolves it against the target directory, normalises the resulting path and
 * guarantees that the final file resides inside {@code dir}. If a file with the
 * desired name already exists, a unique name is generated.</p>
 */
public class ImportingUtilities {

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------

    /**
     * Allocates a {@link File} inside {@code dir} using the supplied {@code name}.
     *
     * <p>The method sanitises {@code name} to reject any path‑traversal
     * characters (e.g. {@code "../"}), removes an optional query part
     * (everything after a {@code '?'}) and guarantees that the resulting file
     * is located within {@code dir}. If a file with the same name already
     * exists, a new name is generated by appending {@code -N} before the file
     * extension.</p>
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (must not be {@code null} or empty)
     * @return a {@link File} object that does not yet exist on disk
     * @throws IllegalArgumentException if {@code dir} or {@code name} is invalid,
     *                                  or if the resolved path would escape {@code dir}
     * @throws IllegalStateException    if the required parent directories cannot be created
     */
    static public File allocateFile(File dir, String name) {
        // -------------------------------------------------------------------
        // Basic argument validation
        // -------------------------------------------------------------------
        if (dir == null) {
            throw new IllegalArgumentException("Target directory must not be null");
        }
        if (name == null) {
            throw new IllegalArgumentException("File name must not be null");
        }

        // -------------------------------------------------------------------
        // Strip optional query part (everything after '?')
        // -------------------------------------------------------------------
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // -------------------------------------------------------------------
        // Reject any path‑separator characters or parent‑directory references.
        // This prevents constructions such as "../secret.txt" or "sub/dir.txt".
        // -------------------------------------------------------------------
        if (name.isEmpty()
                || name.contains("/")
                || name.contains("\\")
                || name.contains("..")) {
            throw new IllegalArgumentException("Invalid file name: potential path traversal");
        }

        // -------------------------------------------------------------------
        // Resolve the name against the target directory and normalise.
        // Normalisation removes any remaining ".." or "." segments.
        // -------------------------------------------------------------------
        Path dirPath = dir.toPath().toAbsolutePath().normalize();
        Path targetPath = dirPath.resolve(name).normalize();

        // -------------------------------------------------------------------
        // Ensure the resolved path is still inside the intended directory.
        // This is the definitive check against directory traversal.
        // -------------------------------------------------------------------
        if (!targetPath.startsWith(dirPath)) {
            throw new IllegalArgumentException("Resolved file path escapes the target directory");
        }

        File file = targetPath.toFile();

        // -------------------------------------------------------------------
        // If a file with the requested name already exists, generate a unique
        // name by appending "-N" before the extension (e.g. "file-2.txt").
        // -------------------------------------------------------------------
        int dot = name.lastIndexOf('.');
        String prefix = (dot < 0) ? name : name.substring(0, dot);
        String suffix = (dot < 0) ? ""   : name.substring(dot);
        int index = 2;

        while (file.exists()) {
            String newName = prefix + "-" + index++ + suffix;
            // The generated name cannot contain path separators, but we keep
            // the same safety checks for completeness.
            targetPath = dirPath.resolve(newName).normalize();
            file = targetPath.toFile();
        }

        // -------------------------------------------------------------------
        // Ensure the parent directory hierarchy exists.
        // If creation fails and the directory still does not exist, abort.
        // -------------------------------------------------------------------
        File parent = file.getParentFile();
        if (parent != null && !parent.isDirectory()) {
            if (!parent.mkdirs() && !parent.isDirectory()) {
                throw new IllegalStateException("Unable to create directories for: " + parent);
            }
        }

        return file;
    }

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------
}
