public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    private static final Logger logger = Logger.getLogger(SecureRandomFactoryBean.class.getName());

    /** Algorithm name to request from {@link SecureRandom#getInstance(String)}. */
    private String algorithm = "SHA1PRNG";

    /** Optional external seed – retained for backward compatibility but ignored. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // -------------------------------------------------------------------
        // Do NOT use an externally supplied seed.
        // -------------------------------------------------------------------
        if (seed != null) {
            logger.warning("SecureRandomFactoryBean was configured with an external seed resource. "
                    + "The seed is ignored to avoid weakening the randomness.");
            // Close the InputStream to avoid a resource leak, but discard its contents.
            try (java.io.InputStream is = seed.getInputStream()) {
