        return signature.getSignedInfo().getReferences().stream().anyMatch(ref -> {
            String uri = ref.getURI();
            // Empty or null URI means the signature is enveloped (covers the whole element)
            if (uri == null || uri.isEmpty()) {
                return true;
            }
            // URI may be prefixed with '#'
            if (uri.startsWith("#")) {
                uri = uri.substring(1);
            }
            return uri.equals(expectedId);
        });
    }

