public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Whitelist pattern for locale strings: language[_COUNTRY] where each part is alphabetic. */
    private static final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,8}(_[a-zA-Z]{2,8})?$");

    // other methods …

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}. The input is validated
     * against a whitelist and checked against the JVM's list of available locales
     * to prevent malicious values (e.g., XSS payloads) from being processed.
     *
     * @param requestedLocale the parameter from the request
     * @return a validated {@link Locale} or {@code null} if the input is invalid / unsupported
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        // If the caller already supplied a Locale, trust it (it cannot contain script data)
        if (requestedLocale instanceof Locale) {
            Locale locale = (Locale) requestedLocale;
            LOG.debug("Applied request locale: {}", locale);
            return locale;
        }

        // Convert to trimmed string for validation
        String localeStr = requestedLocale.toString().trim();

        // Validate format against whitelist pattern
        if (!LOCALE_PATTERN.matcher(localeStr).matches()) {
            LOG.warn("Invalid locale format received: {}", localeStr);
            return null;
        }

        // Build Locale safely (language lower‑case, country upper‑case as per JDK conventions)
        String[] parts = localeStr.split("_", 2);
        Locale locale;
        if (parts.length == 2) {
            locale = new Locale(parts[0].toLowerCase(), parts[1].toUpperCase());
        } else {
            locale = new Locale(parts[0].toLowerCase());
        }

        // Ensure the constructed locale is one that the JVM actually supports
        boolean supported = false;
        for (Locale available : Locale.getAvailableLocales()) {
            if (available.equals(locale)) {
                supported = true;
                break;
            }
        }
        if (!supported) {
            LOG.warn("Requested locale not supported: {}", locale);
            return null;
        }

        LOG.debug("Applied request locale: {}", locale);
        return locale;
    }

    // other methods …
}
