import com.opensymphony.xwork2.util.logging.LoggerFactory;
import java.util.regex.Pattern;

/**
 * Default implementation of {@link ActionMapper} with a hardened
 * {@code cleanupActionName} method.
 *
 * <p>The original implementation attempted to “clean” an invalid action name
 * by stripping out the parts that matched the whitelist pattern.  This approach
 * left any remaining characters untouched, allowing malicious input to slip
 * through.  The patched version follows a strict whitelist strategy: if the
 * supplied name does not fully match the allowed pattern it is rejected
 * outright and a safe default (empty string) is returned.  This eliminates the
 * possibility of partial sanitisation and prevents injection attacks.</p>
 */
public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /**
     * Whitelist of characters that are considered safe for an action name.
     * Only letters, digits, dot, underscore, exclamation, slash,
     * hyphen and forward‑slash are allowed.
     */
    private static final Pattern ALLOWED_ACTION_NAMES = Pattern.compile("[a-zA-Z0-9._!/\\-]*");

    // other methods ...

    /**
     * Cleans up action name from suspicious characters.
     *
     * <p>If the supplied {@code rawActionName} fully matches the whitelist
     * pattern, it is returned (trimmed).  Otherwise the method logs a warning
     * and returns an empty string, effectively rejecting the input.  This
     * strict‑reject approach is safer than attempting to “fix” an invalid
     * name, because any leftover characters could be used for an injection
     * attack.</p>
     *
     * @param rawActionName action name extracted from URI; may be {@code null}
     * @return a safe action name (trimmed) or an empty string if the input is
     *         invalid
     */
    protected String cleanupActionName(final String rawActionName) {
        // Defensive null handling – treat null as an invalid name.
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name; rejecting it and returning an empty string.");
            }
            return "";
        }

        // Trim whitespace to avoid false negatives caused by surrounding spaces.
        String trimmed = rawActionName.trim();

        // Accept only names that completely match the whitelist pattern.
        if (ALLOWED_ACTION_NAMES.matcher(trimmed).matches()) {
            return trimmed;
        }

        // Input does not conform to the whitelist – reject it.
        if (LOG.isWarnEnabled()) {
            LOG.warn(
                "Action/method [{}] does not match allowed action names pattern [{}]; rejecting it.",
                trimmed,
                ALLOWED_ACTION_NAMES.pattern()
            );
        }

        // Return a safe default (empty string) rather than a partially‑sanitised value.
        return "";
    }

