    String principal = principalObj.toString();
    String credentials = credentialsObj.toString();
    if (principal.isEmpty() || credentials.isEmpty()) {
        throw new IllegalArgumentException("Principal and credentials must not be empty");
    }

    JndiLdapContextFactory jndiFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiFactory.getUrl());
    // set authentication mechanism before TLS start
    env.put(Context.SECURITY_AUTHENTICATION, jndiFactory.getAuthenticationMechanism());
    env.put(Context.SECURITY_PRINCIPAL, principal);
    env.put(Context.SECURITY_CREDENTIALS, credentials);

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    try {
        ctx = new InitialLdapContext(env, null);
        // start TLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
