import java.io.InputStream;
import javax.xml.XMLConstants;
import javax.xml.transform.Transformer;
import javax.xml.transform.TransformerConfigurationException;
import javax.xml.transform.TransformerFactory;
import javax.xml.transform.stream.StreamSource;

/**
 * Secure implementation of XSLT rendering.
 *
 * The method creates a {@link Transformer} from a supplied XSLT {@link InputStream}
 * while applying strict security settings to the {@link TransformerFactory} to
 * prevent external entity resolution, stylesheet inclusion and other unsafe
 * operations that could lead to remote code execution.
 */
public class XsltRenderer implements Renderer {

    // -----------------------------------------------------------------------
    // Secure transformer creation
    // -----------------------------------------------------------------------
    /**
     * Creates a {@link Transformer} from the given XSLT template stream.
     *
     * @param templateStream the XSLT template; must not be {@code null}
     * @return a securely configured {@link Transformer}
     * @throws IOException if an I/O error occurs while reading the stream
     * @throws ProcessingFailedException if the transformer cannot be created
     */
    private static Transformer createTransformer(InputStream templateStream) throws IOException {
        if (templateStream == null) {
            throw new IllegalArgumentException("templateStream must not be null");
        }

        // Create a fresh factory for each call – factories are not guaranteed to be thread‑safe.
        TransformerFactory factory = TransformerFactory.newInstance();

        // -------------------------------------------------------------------
        // Apply secure processing features
        // -------------------------------------------------------------------
        try {
            // Disallow all potentially unsafe extensions and limit resource access.
            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

            // Prevent the XSLT processor from accessing external DTDs or stylesheets.
            // An empty string means “no access”.
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
        } catch (TransformerConfigurationException | IllegalArgumentException e) {
            // Configuration failure is a critical error – wrap and re‑throw.
            throw new ProcessingFailedException("Failed to configure secure TransformerFactory", e);
        }

        // -------------------------------------------------------------------
        // Build the transformer using a try‑with‑resources block to guarantee
        // that the InputStream is closed even when an exception is thrown.
        // -------------------------------------------------------------------
        try (InputStream is = templateStream) {
            StreamSource source = new StreamSource(is);
            return factory.newTransformer(source);
        } catch (TransformerConfigurationException e) {
            // Wrap any XSLT compilation errors in a domain‑specific exception.
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        }
    }

    // -----------------------------------------------------------------------
    // Other methods required by the Renderer interface would follow here.
    // -----------------------------------------------------------------------
}
