import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.apache.commons.compress.archivers.ArchiveEntry;

/**
 * Secure implementation of the expand method.
 *
 * The method now:
 * 1. Normalises and resolves each entry against the target directory using {@link Path}.
 * 2. Rejects absolute entry names.
 * 3. Performs a strict {@code startsWith} check on the *real* (canonical) target directory
 *    and on the *real* path of the file that will be created – this prevents
 *    directory‑traversal as well as symlink‑based escape attacks.
 * 4. Uses try‑with‑resources for the output stream.
 */
public class Expander {

    // other methods …

    private void expand(ArchiveEntrySupplier supplier,
                        EntryWriter writer,
                        File targetDirectory) throws IOException {

        // Resolve the target directory to its real (canonical) path once.
        final Path targetDirRealPath = targetDirectory.toPath()
                                                      .toRealPath(LinkOption.NOFOLLOW_LINKS)
                                                      .normalize();

        ArchiveEntry entry;
        while ((entry = supplier.getNextReadableEntry()) != null) {
            String entryName = entry.getName();

            // Defensive checks on the entry name.
            if (entryName == null || entryName.isEmpty()) {
                // Skip empty entries – they cannot be written safely.
                continue;
            }

            // Disallow absolute paths inside the archive.
            Path entryPath = Paths.get(entryName);
            if (entryPath.isAbsolute()) {
                throw new IOException("Archive entry has an absolute path: " + entryName);
            }

            // Resolve the entry against the target directory and normalise it.
            Path resolvedPath = targetDirRealPath.resolve(entryPath).normalize();

            // Ensure the resolved path is still inside the target directory.
            if (!resolvedPath.startsWith(targetDirRealPath)) {
                throw new IOException("Expanding entry '" + entryName
                        + "' would create a file outside of " + targetDirectory);
            }

            File file = resolvedPath.toFile();

            if (entry.isDirectory()) {
                // Create the directory if it does not already exist.
                if (!file.isDirectory() && !file.mkdirs()) {
                    throw new IOException("Failed to create directory " + file);
                }
            } else {
                // Ensure the parent directory exists.
                File parent = file.getParentFile();
                if (!parent.isDirectory() && !parent.mkdirs()) {
                    throw new IOException("Failed to create directory " + parent);
                }

                // Write the entry data.
                try (OutputStream out = Files.newOutputStream(resolvedPath)) {
                    writer.writeEntryDataTo(entry, out);
                }

                // After writing, verify that the *real* path of the created file
                // is still inside the target directory (protects against symlink attacks).
                Path realFilePath = resolvedPath.toRealPath(LinkOption.NOFOLLOW_LINKS).normalize();
                if (!realFilePath.startsWith(targetDirRealPath)) {
                    throw new IOException("Created file '" + realFilePath
                            + "' is outside of the target directory after extraction");
                }
            }
        }
    }

    // other methods …
}
