    /**
     * Implementation of read for STORED entries.
     *
     * <p>This method has been hardened against malformed ZIP entries that
     * can otherwise cause an infinite read loop.  The original implementation
     * could return {@code 0} for a non‑zero {@code length} when the declared
     * size of the entry was {@code 0} or when the calculated {@code toRead}
     * became {@code 0}.  According to the {@link InputStream} contract a
     * non‑negative number other than {@code -1} must be a positive count of
     * bytes read; returning {@code 0} can make callers such as
     * {@code InputStreamReader} loop forever.</p>
     *
     * <p>The new implementation adds defensive checks:</p>
     * <ul>
     *   <li>If the entry size is unknown (negative) we treat it as an
     *       EOF condition – the entry must have been marked as using a
     *       data descriptor and would have been handled earlier.</li>
     *   <li>When the underlying stream signals EOF we immediately return
     *       {@code -1}.</li>
     *   <li>If the calculated number of bytes to return is {@code 0}
     *       (e.g., declared size is {@code 0} or we have already read the
     *       full entry) we also return {@code -1} to correctly signal EOF.</li>
     *   <li>Additional sanity checks guard against malformed archives that
     *       claim a larger size than the actual data.</li>
     * </ul>
     *
     * @param buffer the buffer into which the data is read
     * @param offset the start offset in {@code buffer} at which the data is written
     * @param length the maximum number of bytes to read
     * @return the number of bytes read, or {@code -1} if the end of the entry
     *         has been reached
     * @throws IOException on read errors
     */
    private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
        // Entry uses a data descriptor – the whole entry has already been cached.
        if (current.hasDataDescriptor) {
            if (lastStoredEntry == null) {
                readStoredEntry();               // cache the entry
            }
            return lastStoredEntry.read(buffer, offset, length);
        }

        // Size must be known for a plain STORED entry.  A negative size indicates a malformed
        // archive; treat it as EOF to avoid an endless read.
        final long csize = current.entry.getSize();
        if (csize < 0) {
            return -1;
        }

        // If we have already consumed the declared size, signal EOF.
        if (current.bytesRead >= csize) {
            return -1;
        }

        // Fill the internal buffer if it is exhausted.
        if (buf.position() >= buf.limit()) {
            buf.position(0);
            final int l = in.read(buf.array());
            // Defensive: treat 0 or -1 as EOF (some InputStreams may return 0).
            if (l <= 0) {
                return -1;
            }
            buf.limit(l);
            count(l);
            current.bytesReadFromStream += l;
        }

        // Determine how many bytes we can safely return.
        int toRead = Math.min(buf.remaining(), length);
        long remainingInEntry = csize - current.bytesRead;
        if (remainingInEntry < toRead) {
            toRead = (int) remainingInEntry;
        }

        // If nothing can be read (e.g., declared size is 0), signal EOF.
        if (toRead <= 0) {
            return -1;
        }

        buf.get(buffer, offset, toRead);
        current.bytesRead += toRead;
        return toRead;
    }
