import static java.util.Calendar.*;

public final class CronTab {

    // other methods ...

    /**
     * See {@link #ceil(long)}.
     *
     * This method modifies the given calendar and returns the same object.
     *
     * @throws RareOrImpossibleDateException if the date isn't hit in the 2 years after it indicates an impossible
     * (e.g. Jun 31) date, or at least a date too rare to be useful. This addresses JENKINS-41864 and was added in 2.49
     */
    public Calendar ceil(Calendar cal) {
        // Clone the input calendar to establish a hard limit two years in the future.
        Calendar twoYearsFuture = (Calendar) cal.clone();
        twoYearsFuture.add(Calendar.YEAR, 2);

        // -----------------------------------------------------------------
        // Defensive safeguard: limit the number of outer‑loop iterations.
        // Without this, pathological cron expressions could cause an
        // infinite loop, leading to a denial‑of‑service condition.
        // The limit is deliberately generous (1000) but low enough to
        // guarantee termination even on very complex schedules.
        // -----------------------------------------------------------------
        final int MAX_ITERATIONS = 1000;
        int iteration = 0;

        OUTER:
        while (true) {
            // Abort if we have iterated too many times – treat the schedule as
            // impossible/rare rather than hanging the thread.
            if (++iteration > MAX_ITERATIONS) {
                throw new RareOrImpossibleDateException(
                        "Exceeded maximum adjustment attempts while computing next cron date");
            }

            // If we have stepped beyond the two‑year safety window, the date is
            // considered too rare or impossible.
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
