        // Build the InputSource – handle the three possible ways a StreamSource
        // can provide its payload.
        // -----------------------------------------------------------------
        InputSource inputSource;
        if (source.getReader() != null) {
            inputSource = new InputSource(source.getReader());
        } else if (source.getInputStream() != null) {
            inputSource = new InputSource(source.getInputStream());
        } else if (source.getSystemId() != null) {
            // Fallback to a system‑id only InputSource (e.g., a URL)
            inputSource = new InputSource(source.getSystemId());
        } else {
            throw new IllegalArgumentException("StreamSource does not contain a Reader, InputStream or SystemId");
        }

        inputSource.setSystemId(source.getSystemId());
        inputSource.setPublicId(source.getPublicId());

        // -----------------------------------------------------------------
        // Obtain or create a SAXParserFactory and harden it against XXE.
        // -----------------------------------------------------------------
        SAXParserFactory sfactory = null;
        if (exchange != null) {
            sfactory = exchange.getProperty(Exchange.SAXPARSER_FACTORY, SAXParserFactory.class);
        }
        if (sfactory == null) {
            sfactory = SAXParserFactory.newInstance();
