        configureFactorySecurely(sfactory);

        // -----------------------------------------------------------------
        // Build the XMLReader; any failure is considered fatal for this method.
        // -----------------------------------------------------------------
        XMLReader xmlReader;
        try {
            SAXParser parser = sfactory.newSAXParser();
            xmlReader = parser.getXMLReader();
        } catch (Exception e) {
            LOG.warn("Unable to create a secure XMLReader: {}", e.toString());
            throw new SAXException("Failed to create secure XMLReader", e);
        }

        // -----------------------------------------------------------------
        // Return a fully configured SAXSource.
        // -----------------------------------------------------------------
        return new SAXSource(xmlReader, inputSource);
